begin;

create table if not exists public.fusion_level0_items (
  id uuid primary key default gen_random_uuid(),
  seed_order integer not null unique,
  name text not null check (char_length(btrim(name)) between 1 and 120),
  description text not null check (char_length(btrim(description)) >= 1),
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create unique index if not exists idx_fusion_level0_items_lower_name
  on public.fusion_level0_items(lower(name));

create table if not exists public.fusion_games (
  id uuid primary key default gen_random_uuid(),
  user_id integer not null references public.users(id) on delete cascade,
  title text not null default 'Fusion Game' check (char_length(btrim(title)) between 1 and 180),
  status text not null default 'active' check (status in ('active', 'archived')),
  viewport jsonb not null default '{}'::jsonb,
  settings jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.fusion_game_level0_items (
  id uuid primary key default gen_random_uuid(),
  game_id uuid not null references public.fusion_games(id) on delete cascade,
  user_id integer not null references public.users(id) on delete cascade,
  level0_item_id uuid not null references public.fusion_level0_items(id) on delete restrict,
  initial_order integer not null check (initial_order between 1 and 100),
  position_x real not null default 0,
  position_y real not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (game_id, level0_item_id),
  unique (game_id, initial_order)
);

create table if not exists public.fusion_game_discoveries (
  id uuid primary key default gen_random_uuid(),
  game_id uuid not null references public.fusion_games(id) on delete cascade,
  user_id integer not null references public.users(id) on delete cascade,
  name text not null check (char_length(btrim(name)) between 1 and 120),
  description text not null check (char_length(btrim(description)) >= 1),
  traits jsonb not null default '[]'::jsonb,
  level integer not null check (level between 1 and 5),
  parent_item_ids jsonb not null default '[]'::jsonb,
  ancestor_item_ids jsonb not null default '[]'::jsonb,
  position_x real not null default 0,
  position_y real not null default 0,
  discovered_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists idx_fusion_games_user_updated
  on public.fusion_games(user_id, updated_at desc)
  where status = 'active';

create index if not exists idx_fusion_game_level0_game_order
  on public.fusion_game_level0_items(game_id, initial_order);

create index if not exists idx_fusion_game_discoveries_game_level
  on public.fusion_game_discoveries(game_id, level, discovered_at);

create or replace function public.touch_fusion_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists trg_fusion_level0_items_updated_at on public.fusion_level0_items;
create trigger trg_fusion_level0_items_updated_at
before update on public.fusion_level0_items
for each row execute function public.touch_fusion_updated_at();

drop trigger if exists trg_fusion_games_updated_at on public.fusion_games;
create trigger trg_fusion_games_updated_at
before update on public.fusion_games
for each row execute function public.touch_fusion_updated_at();

drop trigger if exists trg_fusion_game_level0_items_updated_at on public.fusion_game_level0_items;
create trigger trg_fusion_game_level0_items_updated_at
before update on public.fusion_game_level0_items
for each row execute function public.touch_fusion_updated_at();

drop trigger if exists trg_fusion_game_discoveries_updated_at on public.fusion_game_discoveries;
create trigger trg_fusion_game_discoveries_updated_at
before update on public.fusion_game_discoveries
for each row execute function public.touch_fusion_updated_at();

create or replace function public.touch_fusion_game_from_child()
returns trigger
language plpgsql
as $$
begin
  if TG_OP = 'DELETE' then
    update public.fusion_games set updated_at = now() where id = old.game_id;
    return old;
  end if;

  update public.fusion_games set updated_at = now() where id = new.game_id;
  return new;
end;
$$;

drop trigger if exists trg_fusion_level0_touch_game on public.fusion_game_level0_items;
create trigger trg_fusion_level0_touch_game
after insert or update or delete on public.fusion_game_level0_items
for each row execute function public.touch_fusion_game_from_child();

drop trigger if exists trg_fusion_discoveries_touch_game on public.fusion_game_discoveries;
create trigger trg_fusion_discoveries_touch_game
after insert or update or delete on public.fusion_game_discoveries
for each row execute function public.touch_fusion_game_from_child();

alter table public.fusion_level0_items enable row level security;
alter table public.fusion_games enable row level security;
alter table public.fusion_game_level0_items enable row level security;
alter table public.fusion_game_discoveries enable row level security;
drop policy if exists "Signed-in users read Fusion level 0 items" on public.fusion_level0_items;
create policy "Signed-in users read Fusion level 0 items" on public.fusion_level0_items
for select using (auth.role() = 'authenticated');

drop policy if exists "Users manage own fusion games" on public.fusion_games;
create policy "Users manage own fusion games" on public.fusion_games for all
using (exists (select 1 from public.users where users.id = fusion_games.user_id and users.clerk_user_id = auth.uid()::text))
with check (exists (select 1 from public.users where users.id = fusion_games.user_id and users.clerk_user_id = auth.uid()::text));

drop policy if exists "Users manage own fusion game level 0 items" on public.fusion_game_level0_items;
create policy "Users manage own fusion game level 0 items" on public.fusion_game_level0_items for all
using (exists (select 1 from public.users where users.id = fusion_game_level0_items.user_id and users.clerk_user_id = auth.uid()::text))
with check (exists (select 1 from public.users where users.id = fusion_game_level0_items.user_id and users.clerk_user_id = auth.uid()::text));

drop policy if exists "Users manage own fusion discoveries" on public.fusion_game_discoveries;
create policy "Users manage own fusion discoveries" on public.fusion_game_discoveries for all
using (exists (select 1 from public.users where users.id = fusion_game_discoveries.user_id and users.clerk_user_id = auth.uid()::text))
with check (exists (select 1 from public.users where users.id = fusion_game_discoveries.user_id and users.clerk_user_id = auth.uid()::text));

