create or replace function public.create_fusion_game(p_user_id integer)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_auth_user_id text := auth.uid()::text;
  v_game_id uuid;
begin
  if p_user_id is null then
    raise exception 'Missing user id.';
  end if;

  if not exists (
    select 1 from public.users
    where users.id = p_user_id
      and users.clerk_user_id = v_auth_user_id
  ) then
    raise exception 'You can only create Fusion games for your own account.';
  end if;

  insert into public.fusion_games (user_id, title)
  values (p_user_id, 'Fusion Game')
  returning id into v_game_id;

  with random_items as (
    select id, random() as sort_key
    from public.fusion_level0_items
    where active = true
    order by sort_key
    limit 100
  ),
  selected as (
    select id, row_number() over (order by sort_key)::integer as initial_order
    from random_items
  )
  insert into public.fusion_game_level0_items (
    game_id,
    user_id,
    level0_item_id,
    initial_order,
    position_x,
    position_y
  )
  select
    v_game_id,
    p_user_id,
    id,
    initial_order,
    1600 - ((10 - 1) * 86) / 2 + ((initial_order - 1) % 10) * 86,
    1600 - 340 + floor((initial_order - 1) / 10) * 86
  from selected
  order by initial_order;

  return v_game_id;
end;
$$;

grant execute on function public.create_fusion_game(integer) to authenticated;

alter table public.generation_jobs
  drop constraint if exists generation_jobs_module_check;

alter table public.generation_jobs
  add constraint generation_jobs_module_check
  check (module in ('image_generation', 'universe_builder', 'stellar_architect', 'god_engine', 'fusion'));

commit;
